-- Fleet Desk schema (PostgreSQL 17).
--
-- Column names are quoted camelCase so a row maps straight onto the JSON in
-- API_CONTRACT.md with no renaming layer: SELECT * gives the exact shape the
-- frontend expects. Identifiers in generated SQL come from the whitelist in
-- backend/src/schema.js, never from request data.
--
-- IDs are text (the frontend treats them as opaque strings) and are generated by
-- the API, which lets the demo seed keep its stable 'd1', 'c2', 'k3' style ids.

BEGIN;

CREATE TABLE users (
  email         text PRIMARY KEY,
  name          text NOT NULL,
  designation   text NOT NULL DEFAULT '',
  role          text NOT NULL CHECK (role IN ('employee', 'ags', 'lead'))
);

CREATE TABLE drivers (
  id              text PRIMARY KEY,
  "empId"         text NOT NULL UNIQUE,
  name            text NOT NULL,
  mobile          text NOT NULL DEFAULT '',
  "licenseNo"     text NOT NULL UNIQUE,
  "licenseExpiry" date,
  "joinDate"      date,
  status          text NOT NULL DEFAULT 'Active' CHECK (status IN ('Active', 'On leave', 'Inactive')),
  "otRate"        numeric(10, 2) NOT NULL DEFAULT 0 CHECK ("otRate" >= 0),
  nid             text NOT NULL DEFAULT '',
  address         text NOT NULL DEFAULT ''
);

CREATE TABLE cars (
  id                text PRIMARY KEY,
  "regNo"           text NOT NULL UNIQUE,
  make              text NOT NULL DEFAULT '',
  model             text NOT NULL DEFAULT '',
  year              integer CHECK (year BETWEEN 1950 AND 2100),
  seats             integer CHECK (seats BETWEEN 1 AND 99),
  "fuelType"        text NOT NULL CHECK ("fuelType" IN ('Octane', 'Petrol', 'Diesel', 'CNG')),
  "tankCapacity"    numeric(8, 2) CHECK ("tankCapacity" > 0),
  odometer          numeric(12, 1) NOT NULL DEFAULT 0 CHECK (odometer >= 0),
  ownership         text NOT NULL DEFAULT 'Owned' CHECK (ownership IN ('Owned', 'Rented', 'Leased')),
  "driverId"        text REFERENCES drivers (id) ON DELETE RESTRICT,
  status            text NOT NULL DEFAULT 'Available' CHECK (status IN ('Available', 'On trip', 'Maintenance', 'Retired')),
  "fitnessExpiry"   date,
  "taxTokenExpiry"  date,
  "insuranceExpiry" date
);

-- Payment / fuel cards. Only the last four digits are ever stored: no PAN, CVV or PIN.
CREATE TABLE cards (
  id             text PRIMARY KEY,
  provider       text NOT NULL,
  "cardType"     text NOT NULL CHECK ("cardType" IN ('Fleet card', 'Bank card', 'Prepaid card')),
  last4          text NOT NULL CHECK (last4 ~ '^[0-9]{4}$'),
  expiry         text NOT NULL CHECK (expiry ~ '^[0-9]{4}-(0[1-9]|1[0-2])$'),
  "carId"        text REFERENCES cars (id) ON DELETE RESTRICT,
  "monthlyLimit" numeric(12, 2) NOT NULL DEFAULT 0 CHECK ("monthlyLimit" >= 0),
  "issuedOn"     date,
  status         text NOT NULL DEFAULT 'Active' CHECK (status IN ('Active', 'Blocked', 'Closed')),
  notes          text NOT NULL DEFAULT ''
);

CREATE TABLE requisitions (
  id             text PRIMARY KEY,
  "reqNo"        text NOT NULL UNIQUE,
  name           text NOT NULL,
  designation    text NOT NULL DEFAULT '',
  email          text NOT NULL,
  "requiredDate" date NOT NULL,
  "startTime"    time NOT NULL,
  "startPoint"   text NOT NULL,
  destination    text NOT NULL,
  reason         text NOT NULL DEFAULT '',
  status         text NOT NULL DEFAULT 'Pending' CHECK (status IN ('Pending', 'Approved', 'Rejected', 'Cancelled')),
  "createdAt"    timestamptz NOT NULL DEFAULT now(),
  "reviewedAt"   timestamptz,
  "reviewedBy"   text NOT NULL DEFAULT '',
  "driverId"     text REFERENCES drivers (id) ON DELETE RESTRICT,
  "carId"        text REFERENCES cars (id) ON DELETE RESTRICT,
  remarks        text NOT NULL DEFAULT ''
);
CREATE INDEX requisitions_email_idx ON requisitions (lower(email));
CREATE INDEX requisitions_status_date_idx ON requisitions (status, "requiredDate");

-- Daily logbook: one row per car per day.
CREATE TABLE trips (
  id          text PRIMARY KEY,
  date        date NOT NULL,
  "carId"     text NOT NULL REFERENCES cars (id) ON DELETE RESTRICT,
  "driverId"  text REFERENCES drivers (id) ON DELETE RESTRICT,
  "reqId"     text REFERENCES requisitions (id) ON DELETE SET NULL,
  "startTime" time NOT NULL,
  "endTime"   time NOT NULL,
  "startOdo"  numeric(12, 1) NOT NULL CHECK ("startOdo" >= 0),
  "endOdo"    numeric(12, 1) NOT NULL,
  "from"      text NOT NULL DEFAULT '',
  "to"        text NOT NULL DEFAULT '',
  purpose     text NOT NULL DEFAULT '',
  CONSTRAINT trips_one_per_car_per_day UNIQUE (date, "carId"),
  CONSTRAINT trips_odo_order CHECK ("endOdo" >= "startOdo"),
  CONSTRAINT trips_time_order CHECK ("endTime" > "startTime")
);
CREATE INDEX trips_date_idx ON trips (date);
CREATE INDEX trips_driver_date_idx ON trips ("driverId", date);

CREATE TABLE fuel (
  id           text PRIMARY KEY,
  date         date NOT NULL,
  time         time NOT NULL,
  "carId"      text NOT NULL REFERENCES cars (id) ON DELETE RESTRICT,
  "driverId"   text REFERENCES drivers (id) ON DELETE RESTRICT,
  "cardId"     text REFERENCES cards (id) ON DELETE RESTRICT,
  payment      text NOT NULL CHECK (payment IN ('Card', 'Cash')),
  "fuelType"   text NOT NULL CHECK ("fuelType" IN ('Octane', 'Petrol', 'Diesel', 'CNG')),
  qty          numeric(10, 2) NOT NULL CHECK (qty > 0),
  "unitPrice"  numeric(10, 2) NOT NULL CHECK ("unitPrice" >= 0),
  amount       numeric(12, 2) NOT NULL DEFAULT 0,
  odometer     numeric(12, 1) NOT NULL DEFAULT 0 CHECK (odometer >= 0),
  station      text NOT NULL DEFAULT '',
  "receiptNo"  text NOT NULL DEFAULT ''
);
CREATE INDEX fuel_date_idx ON fuel (date);
CREATE INDEX fuel_card_idx ON fuel ("cardId");

-- Every message the system sends, with its delivery status. `attempts` is internal
-- to the retry worker and is not part of the API payload.
CREATE TABLE outbox (
  id        text PRIMARY KEY,
  "sentAt"  timestamptz NOT NULL DEFAULT now(),
  status    text NOT NULL DEFAULT 'Queued' CHECK (status IN ('Queued', 'Sent', 'Failed')),
  kind      text NOT NULL CHECK (kind IN ('notification', 'confirmation', 'rejection')),
  "reqId"   text REFERENCES requisitions (id) ON DELETE SET NULL,
  "to"      text NOT NULL,
  cc        text NOT NULL DEFAULT '',
  "from"    text NOT NULL,
  subject   text NOT NULL,
  html      text NOT NULL,
  attempts  integer NOT NULL DEFAULT 0,
  error     text NOT NULL DEFAULT ''
);
CREATE INDEX outbox_req_idx ON outbox ("reqId");
CREATE INDEX outbox_status_idx ON outbox (status);

-- Single-row settings document (shift and overtime rules, contacts, fuel prices).
CREATE TABLE settings (
  id   integer PRIMARY KEY DEFAULT 1 CHECK (id = 1),
  data jsonb NOT NULL
);

COMMIT;
